contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint firstVal, uint secondVal) public payable {
        require(firstVal > secondVal);

        uint beforeMin = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(firstVal); if (__ESBMC_reverted()) return;
        uint midMin = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(secondVal); if (__ESBMC_reverted()) return;
        uint afterMin = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(midMin == firstVal && afterMin == secondVal && afterMin < midMin);
    }

    receive() external payable {}
}

