    }

    function _run(uint256 firstVal, uint256 secondVal) internal {
        vm.assume(firstVal > secondVal);
        uint256 beforeMin;
        try c.MinSum() returns (uint256 __r) { beforeMin = __r; } catch { return; }
        try c.SetMinSum(firstVal) {} catch { return; }
        uint256 midMin;
        try c.MinSum() returns (uint256 __r) { midMin = __r; } catch { return; }
        try c.SetMinSum(secondVal) {} catch { return; }
        uint256 afterMin;
        try c.MinSum() returns (uint256 __r) { afterMin = __r; } catch { return; }
        assertTrue(midMin == firstVal && afterMin == secondVal && afterMin < midMin);
    }

    function testFuzz_run(uint256 firstVal, uint256 secondVal) public {
